package adb

import (
	"bytes"
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"os"
	"path/filepath"
	"testing"
)

// Compares our encoding with the adbkey.pub generated by the official adb tools.
func TestAndroidPubKeyMatchesAdb(t *testing.T) {
	home, _ := os.UserHomeDir()
	priv, err1 := os.ReadFile(filepath.Join(home, ".android", "adbkey"))
	pub, err2 := os.ReadFile(filepath.Join(home, ".android", "adbkey.pub"))
	if err1 != nil || err2 != nil {
		t.Skip("no ~/.android/adbkey")
	}
	blk, _ := pem.Decode(priv)
	k, err := x509.ParsePKCS8PrivateKey(blk.Bytes)
	if err != nil {
		t.Fatal(err)
	}
	got := androidPubKey(&k.(*rsa.PrivateKey).PublicKey, "x")
	want := bytes.Fields(pub)[0]
	if !bytes.Equal(bytes.Fields(got)[0], want) {
		t.Fatalf("public key encoding mismatch")
	}
}
